import{_ as a,o as e,c as d,ag as o}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"安装中心","description":"在 Ubuntu 24 上按提示安装 InduFrame，保存两个访问地址并开始首次登录。","frontmatter":{"title":"安装中心","description":"在 Ubuntu 24 上按提示安装 InduFrame，保存两个访问地址并开始首次登录。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/install.md","filePath":"zh/安装运维/安装中心.md"}'),i={name:"zh/installation/install.md"};function r(l,t,n,s,c,h){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="安装中心" tabindex="-1">安装中心 <a class="header-anchor" href="#安装中心" aria-label="Permalink to &quot;安装中心&quot;">​</a></h1><p>本页安装的是 InduFrame 的平台中心，装好后就可以从浏览器打开它。<strong>当前版本为 v1.0，优先使用已测试的 Ubuntu 24；其他系统尚未测试。</strong></p><p>已有平台时看<a href="#更新已有平台">更新已有平台</a>；曾保留数据卸载时，按<a href="/induframe-docs/zh/installation/reinstall.html">保留数据后重新安装</a>操作。简短步骤见<a href="/induframe-docs/zh/installation/quick-install.html">快速安装</a>。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><p>完成<a href="/induframe-docs/zh/installation/prepare.html">安装前准备</a>，备好完整安装包、服务器账号、公共地址和自己设置的平台管理员密码。安装需要系统管理权限，不熟悉服务器操作时请维护人员陪同。</p><h2 id="_1-运行安装向导" tabindex="-1">1. 运行安装向导 <a class="header-anchor" href="#_1-运行安装向导" aria-label="Permalink to &quot;1. 运行安装向导&quot;">​</a></h2><p>打开连接到服务器的终端，进入完整安装包解压后的文件夹。可先运行 <code>ls</code>，确认其中有 <code>install.sh</code>，再执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>若提示输入系统密码，输入<strong>当前服务器账号</strong>的密码。它用于取得安装权限，与稍后登录平台的密码不同。</p><p>一开始就出现 <code>1) 更新</code>、<code>2) 取消</code>，表示服务器上已有平台。没有更新计划时，输入 <code>2</code> 或回车取消，不要继续按首次安装操作。</p><h2 id="_2-按提示填写信息" tabindex="-1">2. 按提示填写信息 <a class="header-anchor" href="#_2-按提示填写信息" aria-label="Permalink to &quot;2. 按提示填写信息&quot;">​</a></h2><p>向导一次问一项，方括号内是默认值。确认默认值适合你时，直接回车。</p><table tabindex="0"><thead><tr><th>看到的提示</th><th>建议怎样填写</th></tr></thead><tbody><tr><td>选择存放位置</td><td>没有特殊要求时回车使用 <code>/opt</code>，程序会放在 <code>/opt/induframe</code></td></tr><tr><td>公共访问地址或域名</td><td>填组织成员能访问的服务器 IP 或域名，不填 <code>https://</code> 或网页路径</td></tr><tr><td>公共访问端口</td><td>没有冲突时回车使用 <code>443</code></td></tr><tr><td>管理入口端口</td><td>没有特殊安排时回车使用 <code>18100</code>，不能与公共端口相同</td></tr><tr><td>平台超级管理员用户名</td><td>没有特殊要求时回车使用 <code>admin</code></td></tr></tbody></table><p>不知道公共地址是否正确、或提示端口被占用时，先请维护人员核对，不要随便换地址或停止其他服务。</p><h2 id="_3-选择证书并设置密码" tabindex="-1">3. 选择证书并设置密码 <a class="header-anchor" href="#_3-选择证书并设置密码" aria-label="Permalink to &quot;3. 选择证书并设置密码&quot;">​</a></h2><p>当向导询问 <code>TLS 模式</code>：</p><ul><li><strong>没有专门准备证书</strong>：直接回车，使用默认 <code>self-signed</code>，由安装器生成证书。</li><li><strong>维护人员已准备好证书</strong>：按其安排选择 <code>provided</code>，填写证书、私钥等文件的完整路径。</li></ul><p>使用默认方式后，浏览器可能显示证书信任提醒。请维护人员核对地址和证书后处理，不要关闭安全校验来继续。</p><p>随后按提示输入两次<strong>平台超级管理员初始密码</strong>。建议使用 8–72 个英文字母、数字或半角符号，输入通常显示为星号。两次不同或长度不合适时，在当前步骤重新输入。</p><p>妥善保管这组账号。全新安装后，它用于管理入口，无需再改一次初始密码。完整字段限制见<a href="/induframe-docs/zh/reference/install-options.html">安装参数</a>。</p><h2 id="_4-核对信息并等待完成" tabindex="-1">4. 核对信息并等待完成 <a class="header-anchor" href="#_4-核对信息并等待完成" aria-label="Permalink to &quot;4. 核对信息并等待完成&quot;">​</a></h2><p>向导会汇总程序目录、两个入口和管理员用户名，并显示日志路径。看一遍，确认与准备的信息一致。</p><p>安装分 <strong>14 个阶段</strong>准备运行环境、安装程序并检查服务。保持终端连接，不要同时再启动一轮安装。</p><div class="warning custom-block"><p class="custom-block-title">看到替换或删除提示时先确认</p><p>服务器已有运行环境时，安装器可能询问是否替换，其中其他服务和数据也可能被删除。不清楚原有用途时，请停止并询问维护人员，不要为了继续安装直接同意。</p></div><h2 id="怎样确认装好了" tabindex="-1">怎样确认装好了 <a class="header-anchor" href="#怎样确认装好了" aria-label="Permalink to &quot;怎样确认装好了&quot;">​</a></h2><p>同时确认以下三项：</p><ol><li>14 个阶段已完成，最后是“检查服务状态”。</li><li>出现 <strong>“InduFrame 中心安装完成。”</strong>，安装命令没有报错并正常结束。</li><li>列出<strong>公共入口、管理入口和本次日志路径</strong>。</li></ol><p>只看到阶段编号走到最后，还要等最终完成提示。安装人员核查命令退出状态时应为 <code>0</code>。</p><p>保存两个完整地址，以后直接复制到浏览器：</p><table tabindex="0"><thead><tr><th>地址</th><th>给谁使用</th></tr></thead><tbody><tr><td>公共入口</td><td>组织成员日常登录，使用 HTTPS，默认端口 <code>443</code></td></tr><tr><td>管理入口</td><td>平台超级管理员使用，当前是内网 HTTP 地址，默认端口 <code>18100</code>，带 <code>/admin/</code></td></tr></tbody></table><p>不要把管理入口替换成公共入口，也不要擅自改协议。日志通常在程序目录的 <code>logs</code> 文件夹，以终端打印路径为准。</p><h2 id="更新已有平台" tabindex="-1">更新已有平台 <a class="header-anchor" href="#更新已有平台" aria-label="Permalink to &quot;更新已有平台&quot;">​</a></h2><ol><li>向交付人员确认新完整包适用于当前平台，安排暂停使用并完成需要的备份。</li><li>将新包解压到另一个文件夹，进入后执行 <code>./install.sh</code>。</li><li>出现 <code>1) 更新</code>、<code>2) 取消</code> 时，输入 <code>1</code> 才更新；输入 <code>2</code> 或回车取消。确认前已有平台保持原状。</li><li>更新沿用原安装位置、访问设置和账号。等待最终完成提示，再用原账号检查两个入口及实际业务数据。</li></ol><p>本页不保证任意旧版本都能直接更新。出现数据结构不一致等错误时，保留提示和日志，请交付人员处理。</p><p>完整安装包没有单独的 <code>update.sh</code>；只有明确拿到小型补丁包时，才按其说明运行 <code>./update.sh</code>。</p><h2 id="失败或中断时" tabindex="-1">失败或中断时 <a class="header-anchor" href="#失败或中断时" aria-label="Permalink to &quot;失败或中断时&quot;">​</a></h2><p>记录最后阶段、完整提示和日志位置，先看<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。需排查时按提示保留设置和现场。</p><p>没有完成提示时，不要继续首次设置，也不要自行删除数据、安装记录或反复重装。保留设置只是方便排查，不表示已经安装成功。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>继续<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>，为默认组织管理员设置密码，再按<a href="/induframe-docs/zh/installation/verify.html">确认安装成功</a>检查浏览器访问。</p>',40)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
